mapper.select:
select * from hr_shift
del_flag = '0' and shift_code like concat('%',#{shiftCode},'%') and shift_name like concat('%',#{shiftName},'%') and post_type like concat('%',#{postType},'%') and workday_mask = #{workdayMask} and status = #{status}
order by shift_id desc

mapper.update:
update hr_shift
shift_code = #{shiftCode}, shift_name = #{shiftName}, post_type = #{postType}, workday_mask = #{workdayMask}, summer_extend_enabled = #{summerExtendEnabled}, summer_extend_minutes = #{summerExtendMinutes}, expected_start_time = #{expectedStartTime}, expected_end_time = #{expectedEndTime}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where shift_id = #{shiftId}

